SET @CGUID := 300000003;

-- Petty Criminal uses C++ script, not SmartAI
UPDATE `creature_template`
SET `ScriptName` = 'npc_petty_criminal',
    `AIName` = ''
WHERE `entry` = 46382;

DELETE FROM `smart_scripts`
WHERE (`entryorguid` = 46382 AND `source_type` = 0)
   OR (`entryorguid` IN (-300000011,-300000017,-300000038,-300000042,-300000051,-300000058,-300000071,-300000085,-300000089,-300000097,-300000103,-300000105,-300000114,-300000124,-300000133,-300000135,-300000141,-300000142) AND `source_type` = 0);

